export const meta = {
  "slug": "phosphor-receipt",
  "family": "phosphor",
  "name": "receipt",
  "category": "Commerce",
  "motion": "coin",
  "component": "createPhosphorReceiptIcon"
};

export function createPhosphorReceiptIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
